PRAGMA foreign_keys=ON;CREATE TABLE _ccr_guard(valid INTEGER CHECK(valid=1));CREATE TABLE _ccr_fp(c INTEGER,n INTEGER,a INTEGER,b INTEGER);INSERT INTO _ccr_fp(c,n,a,b) WITH RECURSIVE r(k,v) AS (SELECT row_number() OVER(ORDER BY id),json_array(id,subject_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit) FROM (SELECT id,subject_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit FROM questions WHERE (id GLOB 'q_alevel_bio_[0-9][0-9][0-9]' OR id GLOB 'q_alevel_chem_[0-9][0-9][0-9]' OR id GLOB 'q_alevel_fm_[0-9][0-9][0-9]' OR id GLOB 'q_alevel_math_[0-9][0-9][0-9]' OR id GLOB 'q_alevel_phy_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_addmath_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_bio_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_chem_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_math_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_phy_[0-9][0-9][0-9]'))),w(k,i,n,a,b,v) AS (SELECT k,0,length(v),7,11,v FROM r UNION ALL SELECT k,i+1,n,(a*131+unicode(substr(v,i+1,1)))%2147483647,(b*137+unicode(substr(v,i+1,1)))%2147483629,v FROM w WHERE i<n),f AS (SELECT k,n,a,b FROM w WHERE i=n) SELECT count(*),coalesce(sum(n),0),coalesce(sum((a*k)%2147483647)%2147483647,0),coalesce(sum((b*k)%2147483629)%2147483629,0) FROM f;CREATE TABLE _ccr_sfp(c INTEGER,n INTEGER,a INTEGER,b INTEGER);INSERT INTO _ccr_sfp(c,n,a,b) WITH RECURSIVE r(k,v) AS (SELECT row_number() OVER(ORDER BY id),json_array(id,subject_id,topic_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit) FROM (SELECT id,subject_id,topic_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit FROM questions WHERE (id GLOB 'q_alevel_bio_[0-9][0-9][0-9]' OR id GLOB 'q_alevel_chem_[0-9][0-9][0-9]' OR id GLOB 'q_alevel_fm_[0-9][0-9][0-9]' OR id GLOB 'q_alevel_math_[0-9][0-9][0-9]' OR id GLOB 'q_alevel_phy_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_addmath_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_bio_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_chem_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_math_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_phy_[0-9][0-9][0-9]'))),w(k,i,n,a,b,v) AS (SELECT k,0,length(v),7,11,v FROM r UNION ALL SELECT k,i+1,n,(a*131+unicode(substr(v,i+1,1)))%2147483647,(b*137+unicode(substr(v,i+1,1)))%2147483629,v FROM w WHERE i<n),f AS (SELECT k,n,a,b FROM w WHERE i=n) SELECT count(*),coalesce(sum(n),0),coalesce(sum((a*k)%2147483647)%2147483647,0),coalesce(sum((b*k)%2147483629)%2147483629,0) FROM f;INSERT INTO _ccr_guard SELECT CASE WHEN ((SELECT c=455 AND n=126515 AND a=830621474 AND b=2010748537 FROM _ccr_sfp) OR (SELECT c=455 AND n=137254 AND a=1772630358 AND b=1804962429 FROM _ccr_sfp) OR (SELECT c=455 AND n=137384 AND a=2125807405 AND b=1649402558 FROM _ccr_sfp)) AND (EXISTS(SELECT 1 FROM cambridge_content_reconciliation_state WHERE release_id='cambridge-content-reconciliation-2026-08-28' AND status='completed') OR (NOT EXISTS(SELECT 1 FROM cambridge_content_reconciliation_state) AND NOT EXISTS(SELECT 1 FROM cambridge_content_reconciliation_backup) AND NOT EXISTS(SELECT 1 FROM cambridge_content_reconciliation_audit))) AND NOT EXISTS(SELECT 1 FROM cambridge_content_reconciliation_state WHERE release_id<>'cambridge-content-reconciliation-2026-08-28') AND NOT EXISTS(SELECT 1 FROM cambridge_content_reconciliation_backup WHERE release_id<>'cambridge-content-reconciliation-2026-08-28') AND NOT EXISTS(SELECT 1 FROM cambridge_content_reconciliation_audit WHERE release_id<>'cambridge-content-reconciliation-2026-08-28') THEN 1 ELSE 0 END;DELETE FROM cambridge_content_reconciliation_audit WHERE release_id='cambridge-content-reconciliation-2026-08-28';DELETE FROM cambridge_content_reconciliation_state WHERE release_id='cambridge-content-reconciliation-2026-08-28';DELETE FROM cambridge_content_reconciliation_backup WHERE release_id='cambridge-content-reconciliation-2026-08-28';DROP TABLE cambridge_content_reconciliation_audit;DROP TABLE cambridge_content_reconciliation